import {productMockup} from './product-mockup.js';
import {feedback} from './tactile.js';
import {journeyArt} from './garden-art.js';
import {initForge,openForge,openCollection,supportedFormats,openOffering} from './commerce.js';
import {createGardenWorld} from './pattern-garden-world.js';
const $=id=>document.getElementById(id);
const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const palettes={dawn:{bg:'#15252c',tile:'#324951',ink:'#ecc48c',ring:'#dba1b9',wave:'#9bd3d3',river:'#426d72'},lagoon:{bg:'#13283a',tile:'#27475c',ink:'#e4c587',ring:'#7fd3c9',wave:'#9fbfe6',river:'#51759b'},dusk:{bg:'#262239',tile:'#423956',ink:'#e6b87c',ring:'#c99abf',wave:'#b2b9e0',river:'#69649a'}};
const names={ring:'Mirrorwater',sun:'Amber bloom',wave:'Violet grove'};
const STORAGE='pattern-garden-expedition-v2';
const fresh=()=>({id:crypto.randomUUID(),palette:'dusk',trail:[],discoveries:[],distance:0,events:[{event:'journey-start',at:new Date().toISOString()}],startedAt:new Date().toISOString()});
let nativePaused=false;
addEventListener('craftkit-native-pause',e=>{nativePaused=!!e.detail.paused;if(nativePaused)world?.pause();else if(started)world?.start();});
let state=fresh(),collection=[],artifact=null,revealTurn=0,sound=false,audio,noticeTimer,storageAvailable=true,world=null,saveTimer,started=false;
try{const saved=JSON.parse(localStorage.getItem(STORAGE)||'null');if(saved?.state&&palettes[saved.state.palette]&&Array.isArray(saved.state.trail)&&saved.state.trail.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.z))&&Array.isArray(saved.state.discoveries)&&saved.state.discoveries.every(id=>names[id])&&Array.isArray(saved.state.events)&&Number.isFinite(saved.state.distance))state=saved.state;if(Array.isArray(saved?.collection))collection=saved.collection.filter(a=>a?.design&&typeof a.fingerprint==='string'&&typeof a.svg==='string'&&typeof a.title==='string'&&Array.isArray(a.story));}catch{}
function notify(message){$('notice').textContent=message;$('notice').classList.add('visible');clearTimeout(noticeTimer);noticeTimer=setTimeout(()=>$('notice').classList.remove('visible'),5000);}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({state,collection}));storageAvailable=true;return true;}catch{storageAvailable=false;notify('Browser storage is unavailable. Download your artwork to keep it.');return false;}}
function tone(n=0){if(!sound)return;try{audio ||= new AudioContext();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='sine';osc.frequency.value=[261.63,329.63,392,523.25,659.25][n%5];gain.gain.setValueAtTime(.04,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.7);osc.connect(gain).connect(audio.destination);osc.start();osc.stop(audio.currentTime+.7);}catch{sound=false;$('sound').textContent='Sound unavailable';}}
function render(){const complete=state.discoveries.length===3;$('mission-title').textContent=complete?'Your living palette is complete':'Let the forest color your flight';$('mission-detail').textContent=complete?'Press E or View & save artwork to see your composition.':'Fly through nature to gather color. Press E to view and save your artwork anytime.';$('distance-walked').textContent=Math.round(state.distance)+' m explored';$('collection-count').textContent=collection.length;document.querySelectorAll('[data-echo]').forEach(el=>el.classList.toggle('found',state.discoveries.includes(el.dataset.echo)));document.querySelectorAll('[data-palette]').forEach(b=>{const on=b.dataset.palette===state.palette;b.classList.toggle('selected',on);b.setAttribute('aria-pressed',on);});}
async function fingerprint(design){const bytes=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(design)));return Array.from(new Uint8Array(bytes),b=>b.toString(16).padStart(2,'0')).join('');}
async function download(content,filename,type){if(window.webkit?.messageHandlers?.craftkitExport){const blob=content instanceof Blob?content:new Blob([content],{type});const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(blob);});window.webkit.messageHandlers.craftkitExport.postMessage({filename,base64});notify('Save or share your artwork.');return;}const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);notify('Your download is ready. Check your browser’s downloads.');}
function keep(){const existing=collection.find(a=>a.fingerprint===artifact.fingerprint);if(existing)artifact=existing;else collection.unshift(artifact);const stored=persist();render();return stored;}
function makeSvg(design) {return journeyArt(design);}
function metadata(a) {return {name:a.title,description:a.storyText,image:'data:image/svg+xml;base64,'+btoa(a.svg),attributes:[{trait_type:'Palette',value:a.design.palette},{trait_type:'Distance explored',value:Math.round(a.design.distance||0)},{trait_type:'Game',value:'Pattern Garden'}],properties:{designFingerprint:a.fingerprint,sourceEventId:a.gardenId,rendererVersion:a.design.rendererVersion,createdAt:a.createdAt,events:a.story,collectible:a.collectible||null,chain:null,contract:null,simulated:true,physicalRedemptionIncluded:false}};}
function paintArtifact(a) {const image=new Image();image.onload=()=>{if(artifact?.fingerprint===a.fingerprint)$('artwork').getContext('2d').drawImage(image,0,0,1000,1000);};image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(a.svg);}
function showArtifact(a) {
  artifact=a;paintArtifact(a);$('art-title').textContent=a.title;$('art-story').textContent=a.storyText;$('art-edition').textContent=`ORIGINAL DESIGN / ${a.fingerprint.slice(0,12).toUpperCase()}`;
  const saved=collection.some(x=>x.fingerprint===a.fingerprint);
  $('artifact-actions').innerHTML=`<div class="action-stack"><button id="keep-art" class="primary">${saved?'Saved to collection':'Save to collection'}</button><label class="format-label" for="physical-format">Keep a piece of this journey · optional</label><select id="physical-format"><option value="scarf">A patterned scarf</option><option value="pillow">A pillow cover</option></select><div id="art-product-preview" class="accomplishment-preview"></div><button id="physical-art" class="primary" disabled>Buy this keepsake</button><p class="caption purchase-note">Review the actual product and price before purchase.</p><details><summary>Downloads & collectible</summary><button id="mint-art">${a.collectible?'View demo collectible':'Mint collectible / demo'}</button><div class="download-actions"><button id="download-png">Download PNG</button><button id="download-art">Download SVG</button><button id="download-metadata">Design record</button></div><p class="caption collectible-note">Collectibles are a local simulation; no blockchain transaction or redemption.</p></details></div>${a.collectible?`<div class="collectible-status"><strong>Demo collectible claimed</strong><br>${escape(a.collectible.tokenId)}<br><small>Saved in this browser. No wallet, blockchain transaction, or redemption entitlement.</small></div>`:''}<details class="provenance"><summary>The story behind this piece</summary><dl><dt>Created</dt><dd>${escape(new Date(a.createdAt).toLocaleString())}</dd><dt>Palette</dt><dd>${escape(a.design.palette)}</dd><dt>Journey</dt><dd>${Math.round(a.design.distance||0)} m explored · ${a.design.discoveries?.length||0} living palettes discovered</dd><dt>Choices</dt><dd>${a.story.length} recorded</dd><dt>Design ID</dt><dd>${escape(a.fingerprint)}</dd><dt>Saved</dt><dd>${saved&&storageAvailable?'This browser':'Download to preserve a copy'}</dd></dl><ol class="story-events">${a.story.slice(-8).map(e=>`<li>${escape(e.event==='discover'?`Discovered ${names[e.seed]}`:e.event==='journey-start'?'Entered the Lumen Garden':e.event==='plant'?`Planted ${names[e.seed]} in patch ${e.patch+1}`:e.event==='rotate-stream'?`Turned stream patch ${e.patch-9}`:e.event==='rotate-seed'?`Rotated patch ${e.patch+1}`:e.event==='palette'?`Chose the ${e.palette} palette`:'Revealed the artwork')}</li>`).join('')}</ol></details>`;
  const paintProduct=()=>{$('art-product-preview').innerHTML=productMockup($('physical-format').value,a.svg);};paintProduct();$('physical-format').onchange=paintProduct;
  supportedFormats().then(formats=>{if(artifact?.fingerprint!==a.fingerprint)return;if(formats)for(const option of [...$('physical-format').options])if(!formats.includes(option.value))option.remove();const available=!!$('physical-format').options.length;$('physical-art').disabled=!available;$('art-product-preview').hidden=!available;if(available)paintProduct();else document.querySelector('.purchase-note').textContent='Physical keepsakes are unavailable right now. Your artwork is still yours to save.';}).catch(()=>{if(artifact?.fingerprint!==a.fingerprint)return;$('physical-art').disabled=true;document.querySelector('.purchase-note').textContent='Could not load available keepsakes. Reopen this artwork to try again.';});
  $('keep-art').onclick=()=>{if(keep())notify('Artwork saved in this browser’s collection.');showArtifact(artifact);};
  $('mint-art').onclick=()=>{if(!artifact.collectible)artifact.collectible={tokenId:'DEMO-PG-'+artifact.fingerprint.slice(0,12).toUpperCase(),claimedAt:new Date().toISOString(),simulated:true};const stored=keep();showArtifact(artifact);notify(stored?'Demo collectible claimed. No blockchain transaction occurred.':'Demo collectible created for this session. Download its design record to keep it.');};
  $('download-png').onclick=async()=>{try{const image=new Image();image.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(artifact.svg);await image.decode();const exportCanvas=document.createElement('canvas');exportCanvas.width=exportCanvas.height=2000;exportCanvas.getContext('2d').drawImage(image,0,0,2000,2000);const blob=await new Promise(resolve=>exportCanvas.toBlob(resolve,'image/png'));if(!blob)throw new Error('PNG export failed');download(blob,'pattern-garden-'+artifact.fingerprint.slice(0,8)+'.png','image/png');}catch{notify('PNG export failed. Download the SVG to keep the full-resolution artwork.');}};
  $('download-art').onclick=()=>download(artifact.svg,'pattern-garden-'+artifact.fingerprint.slice(0,8)+'.svg','image/svg+xml');
  $('download-metadata').onclick=()=>download(JSON.stringify(metadata(artifact),null,2),'pattern-garden-'+artifact.fingerprint.slice(0,8)+'.json','application/json');
  $('physical-art').onclick=()=>{const a=artifact,type=$('physical-format').value;keep();$('artifact-dialog').close();openOffering('journey-art',{type,purchaseIntent:true,title:a.title+' / '+(type==='pillow'?'pillow cover':type),sourceEventId:a.gardenId+'-'+a.fingerprint.slice(0,16),design:{...structuredClone(a.design),referenceSvg:a.svg,artworkFingerprint:a.fingerprint},story:structuredClone(a.story),prompt:`Create a ${type==='pillow'?'pillow cover':type} using the exact attached abstract artwork: flowing, layered pigment ribbons on a ${a.design.palette} night ground. Preserve the composition, color transitions, fine lines, and proportions. Use the attached design reference.`});};
  if(!$('artifact-dialog').open)$('artifact-dialog').showModal();
}

async function reveal(){if(state.trail.length<2){notify('Glide a little to paint your first brushstroke.');return;}world?.pause();const turn=++revealTurn,design={rendererVersion:5,palette:state.palette,trail:structuredClone(state.trail),discoveries:[...state.discoveries],distance:Number(state.distance.toFixed(1))},gardenId=state.id,events=structuredClone(state.events);try{const hash=await fingerprint(design);if(turn!==revealTurn)return;const existing=collection.find(a=>a.fingerprint===hash);showArtifact(existing||{fingerprint:hash,gardenId,design,svg:makeSvg(design),title:'Nocturne / '+hash.slice(0,4).toUpperCase(),createdAt:new Date().toISOString(),story:[...events,{event:'artwork-revealed',at:new Date().toISOString()}],storyText:'A flight of '+Math.round(design.distance)+' meters, gathering '+(design.discoveries.length?design.discoveries.map(id=>names[id]).join(', '):'the forest’s light')+'. Your gestures and the colors of the forest became this flowing composition.'});tone(4);}catch{notify('Could not preserve the journey. Your path is still here; try again.');}}
const paused=()=>nativePaused||!started||[...document.querySelectorAll('dialog')].some(d=>d.open);
world=createGardenWorld({canvas:$('garden-world'),getJourney:()=>state,isPaused:paused,onStep:p=>{const last=state.trail.at(-1);if(last)state.distance+=Math.hypot(p.x-last.x,p.z-last.z);state.trail.push(p);if(state.trail.length>550)state.trail.splice(1,1);render();if(!saveTimer)saveTimer=setTimeout(()=>{saveTimer=null;persist();},750);},onDiscover:m=>{if(state.discoveries.includes(m.id))return;feedback('success');state.discoveries.push(m.id);state.events.push({event:'discover',seed:m.id,at:new Date().toISOString()});persist();render();tone(state.discoveries.length);notify(m.name+' discovered. '+m.text);},onReveal:reveal,onTarget:t=>{$('compass').textContent=['N','NW','W','SW','S','SE','E','NE'][((Math.round(t.heading/45)%8)+8)%8]+' · '+(((t.heading%360)+360)%360)+'°';$('waypoint-name').textContent=t.name;$('waypoint-distance').textContent=t.distance+' m';const ready=state.trail.length>=2;$('interact-world').disabled=!ready;$('interact-world').classList.toggle('available',ready);$('interact-label').textContent=ready?'View art & shop':'Fly to paint';}});
$('begin-world').onclick=()=>{if(!world)return;started=true;$('start-world').close();world.start();notify('Glide through the living forest. Each place changes the color of your light.');};
$('pause-world').onclick=()=>{world?.pause();$('pause-dialog').showModal();};
$('pause-close').onclick=$('resume-world').onclick=()=>{$('pause-dialog').close();world?.start();};
$('reset').onclick=()=>{revealTurn++;clearTimeout(saveTimer);saveTimer=null;state=fresh();world?.reset();persist();render();$('pause-dialog').close();world?.start();notify('A new expedition. Your saved artworks remain in your collection.');};
 document.querySelectorAll('[data-palette]').forEach(b=>b.onclick=()=>{if(state.palette!==b.dataset.palette){state.palette=b.dataset.palette;state.events.push({event:'palette',palette:state.palette,at:new Date().toISOString()});persist();render();}});
$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'Sound on':'Sound off';$('sound').setAttribute('aria-pressed',sound);tone(0);};
$('artifact-close').onclick=()=>{$('artifact-dialog').close();world?.start();};
$('collection').onclick=()=>{world?.pause();$('collection-list').innerHTML=collection.length?collection.map((a,i)=>'<button class="collection-item" data-artifact="'+i+'"><img alt="'+escape(a.title)+' artwork" src="data:image/svg+xml;charset=utf-8,'+escape(encodeURIComponent(a.svg))+'"><span><strong>'+escape(a.title)+'</strong><small>'+(a.collectible?'Demo collectible':'Saved artwork')+' · '+escape(new Date(a.createdAt).toLocaleDateString())+'</small></span></button>').join(''):'<p>Fly to paint, then choose View & save artwork → Save to collection. You can also download a PNG or SVG.</p>';document.querySelectorAll('[data-artifact]').forEach(b=>b.onclick=()=>{$('collection-dialog').close();showArtifact(collection[Number(b.dataset.artifact)]);});$('collection-dialog').showModal();};
$('collection-close').onclick=()=>{$('collection-dialog').close();world?.start();};
initForge({gameId:'pattern-garden',preview:()=>artifact?.svg||'',pause:()=>world?.pause(),resume:()=>world?.start()});$('physical-orders').onclick=openCollection;
addEventListener('pagehide',persist);render();$('start-world').showModal();
// Agents can explore through the same movement, collision and discovery actions as players.
const modelContext=document.modelContext;
if(modelContext?.registerTool&&world){const lifecycle=new AbortController();addEventListener('pagehide',()=>lifecycle.abort(),{once:true});const tools=[
{name:'read_garden_journey',title:'Read garden journey',description:'Read expedition progress, explorer position, and the current nearby discovery. Does not change the game.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){return {position:world.position(),discoveries:[...state.discoveries],metersExplored:Math.round(state.distance),paused:paused(),rendering:world.performance(),waypoint:$('waypoint-name').textContent,distance:$('waypoint-distance').textContent,canInteract:!$('interact-world').disabled};}},
{name:'walk_garden',title:'Walk through the garden',description:'Move the explorer through the real 3D garden in a cardinal direction for a short interval, recording the iridescent journey trail. Begin the expedition first. Movement follows the current camera orientation and respects collisions.',inputSchema:{type:'object',properties:{direction:{type:'string',enum:['north','south','east','west']},durationMs:{type:'integer',minimum:100,maximum:5000}},required:['direction','durationMs'],additionalProperties:false},annotations:{readOnlyHint:false},async execute(input){if(!input||Object.keys(input).some(k=>!['direction','durationMs'].includes(k)))throw new Error('Invalid movement input.');return world.walk(input.direction,input.durationMs);}},
{name:'discover_or_preserve_garden',title:'View and save flight artwork',description:'Use the visible E / View & save artwork interaction to preview the current flight composition, after at least two recorded trail points. Does not mint, order or pay.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false},async execute(){if(paused()||$('interact-world').disabled)throw new Error('Begin flying to paint at least two trail points first.');await world.interact();return {discoveries:[...state.discoveries],artworkRevealed:$('artifact-dialog').open};}},
];for(const tool of tools){try{void Promise.resolve(modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}}
